const raw = $input.first().json;
const body = raw.body ?? raw;

const escapeHtml = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const canal = String(body.canal ?? '').trim().toLowerCase();
const destinatario = String(body.destinatario ?? '').trim();
const idioma = String(body.idioma ?? 'pt-BR').trim();
const protocolo = String(body.protocolo ?? `dsp_${Date.now()}`);
const nomeViajante = String(body.nome_viajante ?? 'Viajante').trim();
const roteiro = body.roteiro ?? {};

const origemObj = roteiro.origem ?? {};
const destinoObj = roteiro.destino ?? {};
const origem = typeof body.origem === 'string'
  ? body.origem
  : [origemObj.cidade, origemObj.uf].filter(Boolean).join(' - ') || 'Origem';
const destino = typeof body.destino === 'string'
  ? body.destino
  : [destinoObj.cidade, destinoObj.uf].filter(Boolean).join(' - ') || 'Destino';

const distanciaKm = Math.round(Number(body.distancia_km ?? roteiro.distancia_km ?? 0));
const duracaoMin = Math.round(Number(body.duracao_minutos ?? roteiro.duracao_minutos ?? 0));
const horas = Math.floor(duracaoMin / 60);
const minutos = duracaoMin % 60;
const duracaoTexto = `${horas}h ${minutos}min`;

const resumoGuia = String(body.resumo_guia ?? body.resumo_roteiro ?? roteiro.guia ?? '').trim();
const paradas = Array.isArray(body.paradas) ? body.paradas : (Array.isArray(roteiro.paradas) ? roteiro.paradas : []);

const subjectByLang = {
  en: `Your Smart Tourist Guide Itinerary: ${origem} -> ${destino}`,
  es: `Tu itinerario de viaje: ${origem} -> ${destino}`,
  fr: `Votre itineraire de voyage : ${origem} -> ${destino}`,
  zh: `您的专属行程：${origem} -> ${destino}`,
  hi: `आपका यात्रा कार्यक्रम: ${origem} -> ${destino}`,
  ar: `مسار رحلتك المخصص: ${origem} -> ${destino}`,
  ru: `Ваш персональный маршрут: ${origem} -> ${destino}`,
};
const langPrefix = idioma.split('-')[0].toLowerCase();
const emailSubject = subjectByLang[langPrefix] || `Seu roteiro Guia do Turista Inteligente: ${origem} -> ${destino}`;

const paradasHtml = paradas.length > 0
  ? paradas.map((p) => {
      const titulo = escapeHtml(p.razao_social || p.nome || 'Posto na rota');
      const cnpj = p.cnpj ? ` | CNPJ: ${escapeHtml(p.cnpj)}` : '';
      const combustiveis = Array.isArray(p.combustiveis) && p.combustiveis.length > 0
        ? ` | ${escapeHtml(p.combustiveis.join(', '))}`
        : '';
      return `<li style="margin-bottom:6px;"><strong>${titulo}</strong>${cnpj}${combustiveis}</li>`;
    }).join('')
  : '<li>Nenhuma parada obrigatoria registrada para a autonomia informada.</li>';

const emailHtml = `
<!doctype html>
<html lang="${escapeHtml(idioma)}">
  <body style="margin:0;padding:24px;background:#f4f7fa;font-family:Arial,Helvetica,sans-serif;color:#1b2a34;">
    <table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="max-width:620px;margin:0 auto;background:#ffffff;border-radius:12px;overflow:hidden;border:1px solid #d9e3ec;">
      <tr>
        <td style="background:#0877ad;color:#ffffff;padding:22px 24px;">
          <p style="margin:0;font-size:12px;letter-spacing:0.06em;text-transform:uppercase;opacity:0.9;">Guia do Turista Inteligente · V3</p>
          <h1 style="margin:6px 0 0;font-size:22px;">${escapeHtml(origem)} &rarr; ${escapeHtml(destino)}</h1>
        </td>
      </tr>
      <tr>
        <td style="padding:22px 24px;">
          <p style="margin:0 0 14px;">Ola, <strong>${escapeHtml(nomeViajante)}</strong>! Seu roteiro personalizado esta pronto.</p>
          <table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#eef5fa;border-radius:8px;padding:12px 14px;margin-bottom:18px;">
            <tr>
              <td><strong>Distancia:</strong> ${distanciaKm} km</td>
              <td><strong>Duracao:</strong> ${escapeHtml(duracaoTexto)}</td>
              <td><strong>Protocolo:</strong> ${escapeHtml(protocolo)}</td>
            </tr>
          </table>
          <h2 style="font-size:16px;margin:0 0 8px;color:#0877ad;">Paradas e Postos ANP</h2>
          <ul style="padding-left:18px;margin:0 0 18px;line-height:1.5;">${paradasHtml}</ul>
          <h2 style="font-size:16px;margin:0 0 8px;color:#0877ad;">Guia Personalizado</h2>
          <div style="white-space:pre-line;line-height:1.65;background:#f8fafc;padding:14px;border-radius:8px;border:1px solid #e5edf3;">${escapeHtml(resumoGuia || 'Roteiro pronto para consulta no aplicativo.')}</div>
        </td>
      </tr>
      <tr>
        <td style="padding:14px 24px;background:#f8fafc;font-size:12px;color:#5b6d7a;border-top:1px solid #e5edf3;">
          Despachado automaticamente via n8n (Arquitetura EDA) · Idioma: ${escapeHtml(idioma)}
        </td>
      </tr>
    </table>
  </body>
</html>
`.trim();

const paradasWhatsApp = paradas.length > 0
  ? paradas.map((p, idx) => `${idx + 1}. ${p.razao_social || p.nome}${p.cnpj ? ` (CNPJ ${p.cnpj})` : ''}`).join('\n')
  : 'Sem paradas obrigatorias previstas.';

const whatsappText = [
  `*Guia do Turista Inteligente — V3*`,
  `Ola, ${nomeViajante}! Segue seu roteiro personalizado:`,
  ``,
  `*Rota:* ${origem} -> ${destino}`,
  `*Distancia:* ${distanciaKm} km | *Duracao:* ${duracaoTexto}`,
  `*Protocolo:* ${protocolo}`,
  ``,
  `*Postos ANP / Paradas:*`,
  paradasWhatsApp,
  ``,
  `*Roteiro:*`,
  resumoGuia || 'Confira os detalhes completos no planejador.',
].join('\n');

const destinatarioLimpo = canal === 'whatsapp'
  ? destinatario.replace(/\D/g, '')
  : destinatario;

return [{
  json: {
    canal,
    protocolo,
    idioma,
    destinatario,
    destinatario_limpo: destinatarioLimpo,
    nome_viajante: nomeViajante,
    origem,
    destino,
    email_subject: emailSubject,
    email_html: emailHtml,
    whatsapp_text: whatsappText,
  },
}];
